"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[66389],{60894:e=>{e.exports=JSON.parse('{"functions":[{"name":"setup","desc":"Builds the controller the DataStore specs share: a fresh [DataStoreMock], a [ServiceBag] with an\\nin-process [MessagingServiceMock] injected (so messaging-enabled stores never touch the real\\nMessagingService), and builder methods that own everything they create on one Maid. `Destroy()`\\ntears it all down. Every builder defaults its key to `\\"player_1\\"`; pass a key to override.\\n\\nFields: `mock`, `serviceBag`.\\nBuilders: `newDataStore(key?)`, `newSessionLockedStore(key?, userIdList?)`, `newLockHelper(key?)`\\n(returns `helper, dataStore`), `newMessageHelper(dataStore?)` (returns `helper, dataStore`),\\n`newServer(opts?)` (returns `dataStore, helper?`; `opts` = `{ key?, messaging?, autoCloseOnRequest? }`).\\nHelpers: `awaitOwn(dataStore)` -> boolean (loads and reports whether we own the session).","params":[],"returns":[{"desc":"","lua_type":"{ ... }"}],"function_type":"static","source":{"line":42,"path":"src/datastore/src/Server/DataStoreTestUtils.lua"}},{"name":"setupDataStoreManager","desc":"Builds the controller the [PlayerDataStoreManager] specs share: a session-locked manager wired to\\na fresh [DataStoreMock] (keyed `user_<userId>`), all owned by a Maid.\\n\\nThe manager is bound to close, so `Destroy()` closes the game (see [BindToCloseService.PromiseClose])\\nbefore it tears the objects down. The close is not optional bookkeeping: a store the spec loaded\\nkeeps its auto-save loop running until something removes it, and in the shared test place that loop\\noutlives the spec and fires inside a later package\'s window.\\n\\nRoblox fires PlayerRemoving for every player still in a closing server before the close callbacks\\nsettle, so a spec modelling a shutdown calls `manager:RemovePlayerDataStore(userId)` for those\\nplayers and then `bindToCloseService:PromiseClose()`.\\n\\nFields: `manager`, `mock`, `serviceBag`, `bindToCloseService`.\\nHelpers: `storeAndAwaitLock()` -> boolean -- stores a value on user 1\'s store and waits for the\\nsession-locked load to write the lock envelope.","params":[],"returns":[{"desc":"","lua_type":"{ manager: PlayerDataStoreManager, mock: DataStoreMock, ... }"}],"function_type":"static","source":{"line":130,"path":"src/datastore/src/Server/DataStoreTestUtils.lua"}},{"name":"newServiceBag","desc":"Builds a [ServiceBag] with PlaceMessagingService and [BindToCloseService] registered and\\nInit/Start\'d, owned by the maid.\\nPass a Roblox MessagingService mock to inject it into PlaceMessagingService between Init and Start.","params":[{"name":"maid","desc":"","lua_type":"Maid"},{"name":"robloxMessagingService","desc":"injected when provided","lua_type":"MessagingServiceMock?"}],"returns":[{"desc":"","lua_type":"ServiceBag"}],"function_type":"static","source":{"line":178,"path":"src/datastore/src/Server/DataStoreTestUtils.lua"}},{"name":"newDataStore","desc":"Builds a [DataStore] over `mock` and owns it with the maid.","params":[{"name":"maid","desc":"","lua_type":"Maid"},{"name":"mock","desc":"","lua_type":"DataStoreMock"},{"name":"key","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"DataStore"}],"function_type":"static","source":{"line":198,"path":"src/datastore/src/Server/DataStoreTestUtils.lua"}},{"name":"newSessionLockedStore","desc":"Builds a session-locked [DataStore] over `mock` and owns it with the maid.","params":[{"name":"maid","desc":"","lua_type":"Maid"},{"name":"mock","desc":"","lua_type":"DataStoreMock"},{"name":"key","desc":"","lua_type":"string"},{"name":"userIdList","desc":"defaults to { 1 }","lua_type":"{ number }?"}],"returns":[{"desc":"","lua_type":"DataStore"}],"function_type":"static","source":{"line":211,"path":"src/datastore/src/Server/DataStoreTestUtils.lua"}},{"name":"newMessageHelper","desc":"Builds a [DataStoreMessageHelper] over `dataStore` and owns it with the maid.","params":[{"name":"maid","desc":"","lua_type":"Maid"},{"name":"serviceBag","desc":"","lua_type":"ServiceBag"},{"name":"dataStore","desc":"","lua_type":"DataStore"}],"returns":[{"desc":"","lua_type":"DataStoreMessageHelper"}],"function_type":"static","source":{"line":226,"path":"src/datastore/src/Server/DataStoreTestUtils.lua"}}],"properties":[],"types":[],"name":"DataStoreTestUtils","desc":"Shared setup helpers for the DataStore server specs. The two controller builders --\\n[DataStoreTestUtils.setup] (raw DataStores) and [DataStoreTestUtils.setupDataStoreManager]\\n(a [PlayerDataStoreManager]) -- each own a [Maid] and register everything they create on it, so a\\nsingle `controller:Destroy()` tears it all down: the stores, the auto-save loop each starts once\\nloaded, the helpers, the manager, and the service bag.","source":{"line":11,"path":"src/datastore/src/Server/DataStoreTestUtils.lua"}}')}}]);